using HakutaiKagami.Core.Contracts;
using HakutaiKagami.Core.Messaging;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class EngagementMissionTests
{
    static void At(WorldSession s,long at){while(s.Seconds<at){s.SetPaused(false);long before=s.Seconds;s.AdvanceTo(at);Assert.True(s.Seconds>before);}}
    static WorldSession New(long until=long.MaxValue){var s=new WorldSession(EngagementMission.Create(until:until));At(s,2);s.Open(s.PlayerControl,RegionalWork.Inbox(s).Single(c=>c.CanOpen).Message,s.Revision);At(s,9);Assert.Equal(ResultCode.Accepted,s.SetRegionalActive(true,s.Revision).Code);return s;}
    static void Engage(WorldSession s,string id="request:engage")=>Assert.Equal(ResultCode.Accepted,s.IssueRegional(new(new(id),s.PlayerControl,s.PlayerControl,RegionalAction.Engage,new(0,0),new(10000,0)),s.Revision).Code);
    static void Report(WorldSession s,string id="request:loss-report")=>Assert.Equal(ResultCode.Accepted,s.ReportEngagement(new(id),s.PlayerControl,s.Revision).Code);
    [Fact] public void ExplicitEnemyMissionIsSeparateFromMembershipAndPlacement(){var s=New();Assert.Equal(EngagementMission.EnemyOrganization,s.DiagnosticSnapshot().Engagement!.Terms.EnemyOrganization);Engage(s);var placement=new WorldSession(CreatedCampaign.Create());Assert.Equal(ResultCode.NotAvailable,placement.ReportEngagement(new("request:r"),placement.PlayerControl,placement.Revision).Code);Assert.DoesNotContain(RegionalAction.Engage,placement.DiagnosticSnapshot().CommandMandates![0].Actions);}
    [Fact] public void SameClockContactLossesPreservePeopleAndArmyOwnership(){var s=New();Engage(s);At(s,300);var w=s.DiagnosticSnapshot();Assert.NotEmpty(w.Region!.Losses);Assert.Contains(w.Region.Units,u=>u.Phase is "routed" or "destroyed");Assert.All(w.Region.Units,u=>Assert.Equal(u.InitialSoldiers-u.Soldiers,w.Region.Losses.Where(l=>l.Unit==u.Id).Sum(l=>l.Soldiers)));Assert.Equal(LifeState.Adult,w.Characters.Single(c=>c.Id==s.PlayerControl).Life);Assert.Equal(RetainerStart.House,w.Units.First(u=>u.Commander==s.PlayerControl).Organization);}
    [Fact] public void ExpiredEngagementCannotStartButRetreatStillCan(){var s=New(10);At(s,10);Assert.Equal(ResultCode.NotAvailable,s.IssueRegional(new(new("request:late"),s.PlayerControl,s.PlayerControl,RegionalAction.Engage,new(0,0),new(10000,0)),s.Revision).Code);Assert.Equal(ResultCode.Accepted,s.IssueRegional(new(new("request:safe"),s.PlayerControl,s.PlayerControl,RegionalAction.Retreat,new(0,0),new(10000,0)),s.Revision).Code);}
    [Fact] public void LossReportIsFixedAndNotKnownBeforePhysicalArrival(){var s=New();Engage(s);At(s,40);Report(s);var w=s.DiagnosticSnapshot();var report=w.Engagement!.Reports.Single();string body=EngagementMission.Body(report);Assert.Single(EngagementMission.View(s,s.PlayerControl));Assert.Empty(EngagementMission.View(s,RetainerStart.Lord));var due=w.Couriers!.Missions.Last().ReadyAt;Assert.True(due>s.Seconds);At(s,due-1);Assert.Empty(EngagementMission.View(s,RetainerStart.Lord));At(s,due);Assert.Single(EngagementMission.View(s,RetainerStart.Lord));Assert.Equal(body,EngagementMission.Body(s.DiagnosticSnapshot().Engagement!.Reports.Single()));Assert.DoesNotContain("enemy",body,StringComparison.OrdinalIgnoreCase);}
    [Fact] public void DuplicateReportIdDoesNotResendOrRefreshSnapshot(){var s=New();Report(s);At(s,11);int count=s.DiagnosticSnapshot().Messaging.Messages.Length;string body=EngagementMission.Body(s.DiagnosticSnapshot().Engagement!.Reports.Single());Assert.Equal(ResultCode.AlreadyAccepted,s.ReportEngagement(new("request:loss-report"),s.PlayerControl,s.Revision).Code);Assert.Equal(count,s.DiagnosticSnapshot().Messaging.Messages.Length);Assert.Equal(body,EngagementMission.Body(s.DiagnosticSnapshot().Engagement!.Reports.Single()));Assert.Equal(ResultCode.NotAvailable,s.ReportEngagement(new("request:other"),RetainerStart.Lord,s.Revision).Code);}
    [Theory][InlineData(10)][InlineData(30)][InlineData(45)][InlineData(80)][InlineData(200)]
    public void CombatAndPhysicalReportRestoreExactState(int at){var s=New();Engage(s);At(s,at);Report(s);s.SetPaused(true);var root=Path.Combine(Path.GetTempPath(),"engagement-"+Guid.NewGuid().ToString("N"));var store=new GenerationSaveStore(root,s.DiagnosticSnapshot().Definitions);store.Save(s,"case",s.DiagnosticSnapshot().WorldId,new(0,1));var host=new WorldSessionHost(new WorldSession(EngagementMission.Create()));Assert.Equal(ResultCode.Accepted,host.CommitLoad(store.Prepare("case"),host.Current,host.Current.Revision));var copy=host.Current;Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(copy.DiagnosticSnapshot()));At(s,350);At(copy,350);Assert.Equal(ContractJson.Write(s.DiagnosticSnapshot()),ContractJson.Write(copy.DiagnosticSnapshot()));}
    [Theory][InlineData("enemy")][InlineData("agent")][InlineData("until")][InlineData("basis")]
    public void ForgedMissionTermsAreRejected(string kind){var w=EngagementMission.Create();var t=w.Engagement!.Terms;w.Engagement=w.Engagement with{Terms=kind switch{"enemy"=>t with{EnemyOrganization=RetainerStart.House},"agent"=>t with{Agent=RetainerStart.Lord},"until"=>t with{Until=0},_=>t with{Basis=RetainerStart.Basis}}};Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
    [Theory][InlineData("soldiers")][InlineData("lost")][InlineData("morale")][InlineData("unit")][InlineData("at")]
    public void ReportsCannotBeEditedToLaterOrHiddenNumbers(string kind){var s=New();Report(s);var w=s.DiagnosticSnapshot();var report=w.Engagement!.Reports.Single();var units=report.Units.ToArray();units[0]=kind switch{"soldiers"=>units[0] with{Soldiers=999},"lost"=>units[0] with{Lost=999},"morale"=>units[0] with{Morale=999},"unit"=>units[0] with{Unit=new("unit:region/2/0")},_=>units[0]};w.Engagement.Reports[0]=report with{At=kind=="at"?report.At+1:report.At,Units=units};Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
    [Fact] public void PlacementFixtureKeepsItsOriginalInitialDefinition(){var w=ContractJson.Read<ContractWorld>(File.ReadAllBytes(Path.Combine(AppContext.BaseDirectory,"Fixtures","created-campaign-c30f379-initial.json")));var expected=CreatedCampaign.Create("検証配置家臣");Assert.Null(w.Engagement);Assert.Equal(ContractJson.CanonicalHash(expected),ContractJson.CanonicalHash(w));Assert.Equal(expected.Definitions.Version,w.Definitions.Version);}
    [Fact] public void PlacementRejectsInjectedEngagementModule(){var w=CreatedCampaign.Create();w.Engagement=EngagementMission.Create().Engagement;Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
}
